1	import { create } from "@bufbuild/protobuf";
2	import { timestampFromDate } from "@bufbuild/protobuf/wkt";
3	import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
4	import { memoServiceClient } from "@/connect";
5	import type { Attachment } from "@/types/proto/api/v1/attachment_service_pb";
6	import type { MemoShare } from "@/types/proto/api/v1/memo_service_pb";
7	import {
8	  CreateMemoShareRequestSchema,
9	  DeleteMemoShareRequestSchema,
10	  GetMemoByShareRequestSchema,
11	  ListMemoSharesRequestSchema,
12	  MemoShareSchema,
13	} from "@/types/proto/api/v1/memo_service_pb";
14	
15	// Query keys factory for share-related cache management.
16	export const memoShareKeys = {
17	  all: ["memo-shares"] as const,
18	  list: (memoName: string) => [...memoShareKeys.all, "list", memoName] as const,
19	  byShare: (shareId: string) => [...memoShareKeys.all, "by-share", shareId] as const,
20	};
21	
22	/** Lists all active share links for a memo (creator-only). */
23	export function useMemoShares(memoName: string, options?: { enabled?: boolean }) {
24	  return useQuery({
25	    queryKey: memoShareKeys.list(memoName),
26	    queryFn: async () => {
27	      const response = await memoServiceClient.listMemoShares(create(ListMemoSharesRequestSchema, { parent: memoName }));
28	      return response.memoShares;
29	    },
30	    enabled: options?.enabled ?? !!memoName,
31	  });
32	}
33	
34	/** Creates a new share link for a memo. */
35	export function useCreateMemoShare() {
36	  const queryClient = useQueryClient();
37	  return useMutation({
38	    mutationFn: async ({ memoName, expireTime }: { memoName: string; expireTime?: Date }) => {
39	      const memoShare = create(MemoShareSchema, {
40	        expireTime: expireTime ? timestampFromDate(expireTime) : undefined,
41	      });
42	      const response = await memoServiceClient.createMemoShare(create(CreateMemoShareRequestSchema, { parent: memoName, memoShare }));
43	      return response;
44	    },
45	    onSuccess: (_data, variables) => {
46	      queryClient.invalidateQueries({ queryKey: memoShareKeys.list(variables.memoName) });
47	    },
48	  });
49	}
50	
51	/** Revokes (deletes) a share link. */
52	export function useDeleteMemoShare() {
53	  const queryClient = useQueryClient();
54	  return useMutation({
55	    mutationFn: async ({ name, memoName }: { name: string; memoName: string }) => {
56	      await memoServiceClient.deleteMemoShare(create(DeleteMemoShareRequestSchema, { name }));
57	      return memoName;
58	    },
59	    onSuccess: (_data, variables) => {
60	      queryClient.invalidateQueries({ queryKey: memoShareKeys.list(variables.memoName) });
61	    },
62	  });
63	}
64	
65	/** Resolves a share token to its memo. Used by the public SharedMemo page. */
66	export function useSharedMemo(shareId: string, options?: { enabled?: boolean }) {
67	  return useQuery({
68	    queryKey: memoShareKeys.byShare(shareId),
69	    queryFn: async () => {
70	      const memo = await memoServiceClient.getMemoByShare(create(GetMemoByShareRequestSchema, { shareId }));
71	      return memo;
72	    },
73	    enabled: options?.enabled ?? !!shareId,
74	    retry: false, // Don't retry NOT_FOUND — the link is invalid or expired
75	  });
76	}
77	
78	/**
79	 * Returns the share URL for a MemoShare resource.
80	 * The token is the last path segment of the share name (memos/{uid}/shares/{token}).
81	 */
82	export function getShareUrl(share: MemoShare): string {
83	  const token = share.name.split("/").pop() ?? "";
84	  return `${window.location.origin}/memos/shares/${token}`;
85	}
86	
87	/**
88	 * Returns the token portion of a MemoShare resource name.
89	 * Format: memos/{memo}/shares/{token}
90	 */
91	export function getShareToken(share: MemoShare): string {
92	  return share.name.split("/").pop() ?? "";
93	}
94	
95	/** Rewrites attachment URLs to include a share token for unauthenticated access. */
96	export function withShareAttachmentLinks(attachments: Attachment[], token: string): Attachment[] {
97	  return attachments.map((a) => {
98	    if (a.externalLink) return a;
99	    return { ...a, externalLink: `${window.location.origin}/file/${a.name}/${a.filename}?share_token=${encodeURIComponent(token)}` };
100	  });
101	}
